185	    private ClimateScenarios createChosenClimateChangeScenario(String scenarioName)
186	    {
187	        ClimateScenarios chosenScenario;
188	        switch (scenarioName) {
189	            case "high":
190	                chosenScenario = ClimateScenarios.SCENARIO4;
191	                break;
192	            case "medium":
193	                chosenScenario = ClimateScenarios.SCENARIO3;
194	                break;
195	            case "low":
196	                chosenScenario = ClimateScenarios.SCENARIO2;
197	                break;
198	            default:
199	                chosenScenario = ClimateScenarios.SCENARIO1;
200	        }
