205	    /**
206	     * Find an available location for an object to be created in the simulation field.
207	     * The simulation is chosen at random and is changed if the randomly selected cell
208	     * already contains an object.
209	     *
210	     * @param field (Field) The simulation's field.
211	     * @return (Location) the available location found.
212	     */
213	    private Location findAvailableLocation(Field field)
214	    {
215	        int randomWidth = rand.nextInt(field.getWidth());
216	        int randomDepth = rand.nextInt(field.getDepth());
217	        while (field.getObjectAt(randomDepth,randomWidth) != null) {
218	            randomWidth = rand.nextInt(field.getWidth());
219	            randomDepth = rand.nextInt(field.getDepth());
220	        }
221	        return new Location(randomDepth, randomWidth);
222	    }
