314	    /**
315	     * Calculate the total number of plants to be created.
316	     *
317	     * @return (int) the number of plants.
318	     */
319	    private int getNumberOfPlants()
320	    {
321	        int fieldArea = calculateFieldArea();
322	        return (int)(fieldArea * habitatPlantConcentration);
323	    }
